import forgelib as F
G = F.make(slug="the-forge-bard-quest", order=8, kw="bard quest",
 title="The Forge Bard Quest: Lost Guitar & Secret Quests",
 h1="The Forge Bard Quest: Find the Lost Guitar (Plus the Best Secret Quests)",
 desc="The Forge Bard quest walkthrough: where the Lost Guitar is, the Unknown Key reward, the Arcane Pickaxe it unlocks, and other secret quests worth doing first.",
 kw2=["the forge lost guitar","the forge bard guitar location","the forge secret quests","the forge arcane pickaxe","the forge best quests"],
 related=["the-forge-pickaxe-progression","the-forge-beginners-guide","the-forge-goblin-cave","the-forge-money-guide"],
 ids=["s62LkUlDC2c","Q79dFbN6q6w","X1J3NEcd7As","QDf0FbMN_2I"],
 lead="The <strong>Bard quest</strong> (\"Bard's Lost Guitar\") is a short Stonewake's Cross side quest that leads to one of the best early pickaxes. Fridge has a full walkthrough, a Short on the guitar's location, and two videos on secret quests. This page combines all of them.",
 heading="Watch Fridge's Bard and Secret Quest Videos",
 sections=[
 ("bard","Where to Find the Bard","""<p>The Bard sits by the <strong>campfire</strong> near spawn in Stonewake's Cross, to the left of the Forge and past Maria's Potion Shop. He's a weary musician who has lost his guitar, according to the Forge Wiki. Talk to him to start <em>Lost Guitar</em>.</p>"""),
 ("guitar","How to Complete the Lost Guitar Quest","""<ol class="steps"><li>Talk to the <strong>Bard</strong> at the campfire to accept the quest.</li><li>Go to the cave entrance and look for the <strong>green leaves</strong> beside it. They hide a secret cave, as described on the Forge Wiki's Arcane Pickaxe page.</li><li>Pick up the <strong>guitar</strong> inside the secret cave.</li><li>Bring it back to the Bard to finish the quest. You get 250 XP, 500 Gold and the <strong>Unknown Key</strong>.</li><li>Use the key on the locked gate of the <strong>Fallen Angel's Cave</strong>. Pro Game Guides says to keep to the right wall inside the Stonewake cave until you see it.</li></ol>"""),
 ("arcane","What the Unknown Key Unlocks: The Arcane Pickaxe","""<p>Behind the gate is the <strong>Arcane Pickaxe</strong>. It has 115 Mine Power, +10% speed, +50% Luck and 3 rune slots. It's Legendary and costs 125,000 Gold, or 110,000 with the Goblin race discount. Pro Game Guides calls it the pickaxe to come back for once you've earned money on Island 2. The Forge Wiki's current guide is less keen: it marks the Bard quest as low priority on World 1 because the Arcane Pickaxe is \"not viable\" next to newer pickaxes, but top priority on World 2 alongside Sensei Moro.</p>"""),
 ("secret","Other Secret Quests Worth Doing","""<p>Fridge's \"secret quests\" videos cover hidden quest givers that many players walk past. These are the ones the wiki and Pro Game Guides confirm:</p>
<div class="table-wrap"><table><caption>Hidden and side quests in The Forge</caption><thead><tr><th scope="col">Quest giver</th><th scope="col">Where</th><th scope="col">What you do</th></tr></thead><tbody>
<tr><td>Tomo the Explorist (Lost Cat)</td><td>Stonewake's Cross, path to the Wizard's Tower</td><td>Find his cat in the Goblin area for extra XP</td></tr>
<tr><td>Isaac (Cure for Isaac)</td><td>Forgotten Kingdom, camp by the Ruined Cave</td><td>Bring a Health Potion I (Health Potion II won't work)</td></tr>
<tr><td>Line (Line's Needs)</td><td>Forgotten Kingdom, path to the Wizard's Tower</td><td>Give Demonite for a badge and XP</td></tr>
<tr><td>Masked Stranger</td><td>Forgotten Kingdom and Frostspire</td><td>Repeatable skeleton and pirate hunts</td></tr>
<tr><td>Skal (Demonite Key)</td><td>Volcanic Depths</td><td>Bring 3 Demonite for the Demonic Pickaxe key</td></tr></tbody></table></div>
<p>For the biggest rewards, the wiki's priority list puts Sensei Moro's questline first on every island. More quest walkthroughs: the <a href="the-forge-goblin-cave.html">Goblin Cave</a> and the <a href="the-forge-raven-cave.html">Raven Cave</a>.</p>""")],
 faq=[("Where is the Bard's guitar in The Forge?","In a secret cave hidden behind green leaves beside the Stonewake's Cross cave entrance."),
      ("What do you get for the Bard quest in The Forge?","250 XP, 500 Gold and the Unknown Key, which opens the Fallen Angel's Cave and the Arcane Pickaxe."),
      ("How much is the Arcane Pickaxe in The Forge?","125,000 Gold, or 110,000 with the Goblin race discount.")],
 sources=[F.wiki("Bard"),F.wiki("Lost_Guitar","Lost Guitar quest"),F.wiki("Arcane_Pickaxe","Arcane Pickaxe"),F.wiki("Guide","Community guide: quest priority"),F.wiki("Skal"),("Pro Game Guides: The Forge quest NPCs","https://progameguides.com/roblox/the-forge-map-all-islands-locations-level-requirements/")],
 howto=("How to complete the Bard's Lost Guitar quest",[("Talk to the Bard","Find the Bard by the Stonewake's Cross campfire and accept Lost Guitar.","bard"),("Find the secret cave","Go through the green leaves beside the cave entrance.","guitar"),("Grab the guitar","Pick up the guitar inside the secret cave.","guitar"),("Return it","Give the guitar to the Bard for the Unknown Key.","guitar"),("Open the gate","Use the key on the Fallen Angel's Cave gate.","arcane")]))
